<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DormitoryExtendedController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('dormitory_manager')||$r->user()->canDo('dormitory.manage'),403);}
public function visitors(Request $r){$this->manage($r);$rows=DB::table('dormitory_visitors as v')->join('students as s','s.id','=','v.host_student_id')->join('dormitory_buildings as b','b.id','=','v.dormitory_building_id')->select('v.*','s.last_name','s.first_name','b.name building_name')->orderByDesc('v.entered_at')->limit(200)->get();$students=DB::table('dormitory_stays as st')->join('students as s','s.id','=','st.student_id')->where('st.status','active')->select('s.id','s.last_name','s.first_name')->orderBy('s.last_name')->get();$buildings=DB::table('dormitory_buildings')->where('active',1)->get();return view('dormitory.visitors',compact('rows','students','buildings'));}
public function visitorStore(Request $r){$this->manage($r);$d=$r->validate(['dormitory_building_id'=>'required|exists:dormitory_buildings,id','host_student_id'=>'required|exists:students,id','visitor_name'=>'required|string|max:255','document_hint'=>'nullable|string|max:100','entered_at'=>'required|date','note'=>'nullable|string|max:2000']);DB::table('dormitory_visitors')->insert($d+['registered_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function visitorExit(Request $r,$id){$this->manage($r);DB::table('dormitory_visitors')->where('id',$id)->whereNull('left_at')->update(['left_at'=>now(),'updated_at'=>now()]);return back();}
public function transfer(Request $r,$stay){$this->manage($r);$old=DB::table('dormitory_stays')->find($stay);abort_if(!$old||$old->status!=='active',404);$d=$r->validate(['dormitory_place_id'=>'required|exists:dormitory_places,id','transferred_on'=>'required|date','order_number'=>'nullable|string|max:100','reason'=>'nullable|string|max:3000']);DB::transaction(function()use($old,$d,$r){$np=DB::table('dormitory_places')->where('id',$d['dormitory_place_id'])->lockForUpdate()->first();abort_if(!$np||$np->status!=='available',422,'Новое место занято');DB::table('dormitory_stays')->where('id',$old->id)->update(['status'=>'closed','check_out_on'=>$d['transferred_on'],'updated_at'=>now()]);DB::table('dormitory_places')->where('id',$old->dormitory_place_id)->update(['status'=>'available','updated_at'=>now()]);$nid=DB::table('dormitory_stays')->insertGetId(['student_id'=>$old->student_id,'dormitory_place_id'=>$np->id,'academic_period_id'=>$old->academic_period_id,'check_in_on'=>$d['transferred_on'],'order_number'=>$d['order_number']??null,'status'=>'active','note'=>$d['reason']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('dormitory_places')->where('id',$np->id)->update(['status'=>'occupied','updated_at'=>now()]);DB::table('dormitory_transfers')->insert(['student_id'=>$old->student_id,'from_stay_id'=>$old->id,'to_stay_id'=>$nid,'transferred_on'=>$d['transferred_on'],'order_number'=>$d['order_number']??null,'reason'=>$d['reason']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);});return back();}
public function maintenance(Request $r){$this->manage($r);$rows=DB::table('dormitory_maintenance_requests as m')->join('dormitory_rooms as rm','rm.id','=','m.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->select('m.*','rm.number room_number','b.name building_name')->orderByRaw("case when m.status='new' then 0 when m.status='work' then 1 else 2 end")->orderByDesc('m.created_at')->get();$rooms=DB::table('dormitory_rooms as r')->join('dormitory_buildings as b','b.id','=','r.dormitory_building_id')->select('r.id','r.number','b.name building_name')->get();return view('dormitory.maintenance',compact('rows','rooms'));}
public function maintenanceStore(Request $r){$this->manage($r);$d=$r->validate(['dormitory_room_id'=>'required|exists:dormitory_rooms,id','category'=>'required|string|max:100','priority'=>'required|in:normal,high,emergency','description'=>'required|string|max:5000']);DB::table('dormitory_maintenance_requests')->insert($d+['created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function maintenanceDone(Request $r,$id){$this->manage($r);$d=$r->validate(['result'=>'required|string|max:5000']);DB::table('dormitory_maintenance_requests')->where('id',$id)->update(['status'=>'done','result'=>$d['result'],'completed_at'=>now(),'updated_at'=>now()]);return back();}
public function night(Request $r){$this->manage($r);$rows=DB::table('dormitory_night_checks as n')->join('dormitory_rooms as rm','rm.id','=','n.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->select('n.*','rm.number room_number','b.name building_name')->orderByDesc('n.checked_at')->limit(200)->get();$rooms=DB::table('dormitory_rooms as r')->join('dormitory_buildings as b','b.id','=','r.dormitory_building_id')->select('r.id','r.number','b.name building_name')->get();return view('dormitory.night',compact('rows','rooms'));}
public function nightStore(Request $r){$this->manage($r);$d=$r->validate(['dormitory_room_id'=>'required|exists:dormitory_rooms,id','checked_at'=>'required|date','present_count'=>'required|integer|min:0','absent_count'=>'required|integer|min:0','note'=>'nullable|string|max:3000']);DB::table('dormitory_night_checks')->insert($d+['checked_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
}